# generated by tools/ail2py.py from binary_layout_main.ail; edit the .ail until onelang s16
from binary_layout import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 5:
        print('usage: binary_layout pad|repeat input output count', file=sys.stderr)
        return 2
    mode = sys.argv[1]
    if mode != 'pad' and mode != 'repeat':
        print('unknown mode', file=sys.stderr)
        return 2
    try:
        count = int(sys.argv[4])
        data = read_bytes(sys.argv[2])
        result = b''
        if mode == 'pad':
            result = binary_pad(data, count)
        else:
            result = binary_repeat(data, count)
        write_bytes(sys.argv[3], result)
        return 0
    except ValueError:
        print('invalid count or width', file=sys.stderr)
        return 2
    except OSError:
        print('file operation failed', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
